const signatureTrustRootFailed = `-- name: SignatureTrustRootFailed :one
UPDATE signature_settings
   SET trust_root_error = left($1::text, 2000), trust_root_error_at = now(),
       trust_root_reported_at = CASE WHEN trust_root_reported_at IS NULL OR trust_root_reported_at <= now() - interval '1 day'
                                     THEN now() ELSE trust_root_reported_at END
 WHERE id
RETURNING (trust_root_reported_at = now())::boolean AS report
`

// A run of the task that failed: the failure is kept, and report says whether the event signature.trust_root.failed is due (at most
// once a day, R-SIG-039).
func (q *Queries) SignatureTrustRootFailed(ctx context.Context, detail string) (bool, error) {
	row := q.db.QueryRow(ctx, signatureTrustRootFailed, detail)
	var report bool
	err := row.Scan(&report)
	return report, err
}

const signatureTrustRootSucceeded = `-- name: SignatureTrustRootSucceeded :exec
UPDATE signature_settings SET trust_root_error = NULL, trust_root_error_at = NULL WHERE id
`

// A run of the task that succeeded clears the last failure.
func (q *Queries) SignatureTrustRootSucceeded(ctx context.Context) error {
	_, err := q.db.Exec(ctx, signatureTrustRootSucceeded)
	return err
}

